    let amount: f64 = input.trim().parse().map_err(|_| "金额无效".to_owned())?;
    Ok((amount * 100.0) as i64)
}

pub fn format_cents(cents: i64) -> String {
    format!("{}.{:02}", cents / 100, (cents % 100).abs())
}
"}

{"output":"use crate::amount::parse_cents;

#[derive(Clone, Debug, PartialEq, Eq)]
pub enum Event {
    Deposit { id: String, account: String, cents: i64 },
    Transfer { id: String, from: String, to: String, cents: i64 },
}

impl Event {
    pub fn id(&self) -> &str {
        match self {
            Self::Deposit { id, .. } | Self::Transfer { id, .. } => id,
        }
    }
}

pub fn parse_events(input: &str) -> Result<Vec<Event>, String> {
    input.lines().filter(|line| !line.is_empty() && !line.starts_with('#'))
        .enumerate().map(|(index, line)| {
            let fields: Vec<_> = line.split(',').collect();
            let result = match fields.as_slice() {
                ["deposit", id, account, amount] => parse_cents(amount).map(|cents| Event::Deposit {
                    id: (*id).to_owned(), account: (*account).to_owned(), cents,
                }),
                ["transfer", id, from, to, amount] => parse_cents(amount).map(|cents| Event::Transfer {
                    id: (*id).to_owned(), from: (*from).to_owned(), to: (*to).to_owned(), cents,
                }),
                _ => Err("流水格式无效".to_owned()),
            };
            result.map_err(|error| format!("第 {} 行：{}", index + 1, error))
        }).collect()
}
"}

{"output":"use std::collections::BTreeMap;
use crate::csv::Event;

#[derive(Debug, Default)]
pub struct Ledger {
    balances: BTreeMap<String, i64>,
    requests: BTreeMap<String, Event>,
}

impl Ledger {
    pub fn new() -> Self { Self::default() }

    pub fn balance(&self, account: &str) -> Option<i64> { self.balances.get(account).copied() }

    pub fn balances(&self) -> &BTreeMap<String, i64> { &self.balances }

    pub fn apply(&mut self, event: &Event) -> Result<bool, String> {
        if self.requests.contains_key(event.id()) { return Ok(false); }
        self.requests.insert(event.id().to_owned(), event.clone());
        match event {
            Event::Deposit { account, cents, .. } => {
                *self.balances.entry(account.clone()).or_default() += cents;
            }
            Event::Transfer { from, to, cents, .. } => {
                let source = self.balances.get_mut(from).ok_or("源账户不存在")?;
                if *source < *cents { return Err("余额不足".to_owned()); }
                *source -= cents;
                let target = self.balances.get_mut(to).ok_or("目标账户不存在")?;
                *target += cents;
            }
        }
        Ok(true)
    }
}
"}

{"output":"pub mod amount;
pub mod csv;
pub mod ledger;
pub mod user_policy;

use amount::format_cents;
use csv::parse_events;
use ledger::Ledger;

pub fn run(input: &str) -> Result<String, String> {
    let mut ledger = Ledger::new();
    for event in parse_events(input)? {
        let _ = ledger.apply(&event);
    }
    let mut output = format!("{}\n", user_policy::REPORT_HEADER);
    for (account, cents) in ledger.balances() {
        output.push_str(&format!("{},{}\n", account, format_cents(*cents)));
    }
    Ok(output)
}
"}

