use amount::format_cents;
use csv::parse_events;
use ledger::Ledger;

/// 从完整流水生成报表。
///
/// 任何解析或记账错误都会让整个函数返回错误：不会输出部分报表。
/// 重复的成功请求被去重（`Ledger::apply` 返回 `Ok(false)`），不影响报表。
pub fn run(input: &str) -> Result<String, String> {
    let mut ledger = Ledger::new();
    for event in parse_events(input)? {
        ledger.apply(&event)?;
    }

    // 先构造完整字符串再返回，调用方因此不可能看到半截报表。
    let mut output = String::new();
    output.push_str(user_policy::REPORT_HEADER);
    output.push('\n');
    // BTreeMap 已按账户名（字典序）排序。
    for (account, cents) in ledger.balances() {
        output.push_str(account);
        output.push(',');
        output.push_str(&format_cents(*cents));
        output.push('\n');
    }
    Ok(output)
}

